import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Sales document convert — production readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Sales document convert — production readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/sales-document-convert-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Sales document convert — production readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/sales-document-convert-production-readiness"}]]},"headers":[],"relativePath":"deployment/sales-document-convert-production-readiness.md","filePath":"deployment/sales-document-convert-production-readiness.md","lastUpdated":1787835227000}'),r={name:"deployment/sales-document-convert-production-readiness.md"};function i(s,e,d,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="sales-document-convert-—-production-readiness" tabindex="-1">Sales document convert — production readiness <a class="header-anchor" href="#sales-document-convert-—-production-readiness" aria-label="Permalink to &quot;Sales document convert — production readiness&quot;">​</a></h1><p><strong>Decision: Go</strong> (migrate-first) · 19 Aug 2026</p><p>Catalog versions after migrate: <strong>quotations 1.4.1</strong>, <strong>contracts 1.2.1</strong>, <strong>estimates 1.3.3</strong>, <strong>invoices 1.6.1</strong>.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>One-shot quote/estimate convert-to-invoice, repeatable contract progress billing, and integrity hardening from the production readiness audit (lock races, soft-delete messaging, estimate entitlement, repeat-billing acknowledgement, unique <code>estimate_id</code>).</p><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to &quot;Gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td><code>lockForUpdate</code> on quote/estimate convert (+ linked quotation for estimates)</td><td>Pass</td></tr><tr><td>Unique nullable <code>customer_invoices.estimate_id</code></td><td>Pass</td></tr><tr><td>Soft Invoices entitlement on estimate convert</td><td>Pass</td></tr><tr><td>Soft-deleted invoice blocks convert with restore/force-delete guidance</td><td>Pass</td></tr><tr><td>Contract 2nd+ bill requires <code>acknowledge_repeat_billing=true</code></td><td>Pass</td></tr><tr><td>Estimates UI convert gated on <code>hasModule(&#39;invoices&#39;)</code></td><td>Pass</td></tr><tr><td>Stop recurring refetches invoice detail before dialog</td><td>Pass</td></tr><tr><td>Pest convert / soft-delete / entitlement / acknowledge cases</td><td>Pass</td></tr><tr><td>Billing Playwright (prior session)</td><td>Pass (13/13)</td></tr></tbody></table><h2 id="accepted-by-design" tabindex="-1">Accepted by design <a class="header-anchor" href="#accepted-by-design" aria-label="Permalink to &quot;Accepted by design&quot;">​</a></h2><ul><li><code>*.convert</code> does <strong>not</strong> require <code>invoices.create</code> (soft-convert pattern, same as PO → expense). Default admin/manager roles include both.</li><li><code>quotation_id</code> stays non-unique so contracts can bill repeatedly.</li><li>Soft-deleted invoices still block one-shot convert (integrity). Ops restore or force-delete to unblock.</li></ul><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><ol><li>Backend: <code>composer install</code> (if needed) → <code>php artisan migrate</code> (unique <code>estimate_id</code> + catalog bumps through <strong>1.4.1 / 1.2.1 / 1.3.3 / 1.6.1</strong>).</li><li>Confirm scheduler still runs <code>invoices:generate-recurring</code> (unchanged).</li><li>Deploy Frontend after Backend (acknowledge payload + estimate Invoices gate + stop refetch).</li><li>Custom roles: ensure <code>quotations.convert</code> / <code>contracts.convert</code> / <code>estimates.convert</code> where needed (defaults updated earlier).</li></ol><h2 id="staging-smoke" tabindex="-1">Staging smoke <a class="header-anchor" href="#staging-smoke" aria-label="Permalink to &quot;Staging smoke&quot;">​</a></h2><ol><li>Send quote → convert → convert again → 422; soft-delete invoice → convert still 422 with “in trash” message; force-delete → convert allowed again.</li><li>Estimate without Invoices entitled → convert 422 on <code>estimate</code>.</li><li>Active contract → create invoice (no acknowledge) → create again without flag → 422 on <code>acknowledge_repeat_billing</code> → with <code>true</code> → 201.</li><li>Recurring invoice: send → generate → Stop recurring shows void-latest checkbox when a draft child exists.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><ul><li>Revert SPA first if API clients cannot send <code>acknowledge_repeat_billing</code>.</li><li>Do not drop the unique <code>estimate_id</code> index in production without a data plan; down migration exists for local only.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/deployment/upgrade">Upgrade</a> · <a href="/changelog/">Changelog</a> · <a href="/api/tenant-v1-quotations">Quotations API</a> · <a href="/api/tenant-v1-contracts">Contracts API</a> · <a href="/api/tenant-v1-estimates">Estimates API</a></li></ul>',17)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
